scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Calculate n! mod MOD
    factorial = 1
    for i in range(1, n + 1):
        factorial = (factorial * i) % mod

    return float(factorial)

